import Foundation

/// Release tags are generated by CI, so compare publication time with the
/// embedded build time rather than treating the release title as a version.
public struct InstalledRelease {
    public let tag: String?
    public let builtAt: Date?
    public init(tag: String?, builtAt: Date?) { self.tag = tag; self.builtAt = builtAt }
    public init(info: [String: Any]) {
        tag = info["PostinoReleaseTag"] as? String
        builtAt = (info["PostinoBuildDate"] as? String).flatMap(Self.date)
    }
    static func date(_ value: String) -> Date? {
        let formatter = ISO8601DateFormatter()
        if let date = formatter.date(from: value) { return date }
        formatter.formatOptions.insert(.withFractionalSeconds)
        return formatter.date(from: value)
    }
}

public struct AppRelease: Decodable, Equatable {
    public struct Asset: Decodable, Equatable {
        public let name: String
        public let url: URL
        public let size: Int64
        public let digest: String?
        enum CodingKeys: String, CodingKey { case name, url = "browser_download_url", size, digest }
    }
    public let tag: String
    public let name: String?
    public let url: URL
    public let publishedAt: String?
    public let draft: Bool
    public let prerelease: Bool
    public let assets: [Asset]
    public var displayName: String { name.flatMap { $0.isEmpty ? nil : $0 } ?? tag }
    enum CodingKeys: String, CodingKey {
        case tag = "tag_name", name, url = "html_url", publishedAt = "published_at", draft, prerelease, assets
    }
    public func updateAsset() throws -> Asset {
        let name = "Postino-" + tag.replacingOccurrences(of: "postino-", with: "", options: .anchored) + ".zip"
        guard let asset = assets.first(where: { $0.name == name }),
              asset.url.scheme == "https", asset.url.host == "github.com", asset.url.user == nil,
              asset.url.password == nil, asset.url.port == nil,
              asset.url.path == "/Dome015/postino/releases/download/\(tag)/\(name)",
              asset.size > 0, asset.size <= 200_000_000,
              let digest = asset.digest, digest.range(of: "^sha256:[a-fA-F0-9]{64}$", options: .regularExpression) != nil else {
            throw UpdateInstallError.message("This release does not include a supported Postino download with a SHA-256 checksum.")
        }
        return asset
    }
}

public enum AppUpdateResult: Equatable {
    case available(AppRelease)
    case current
    case unknownBuild(AppRelease)
}

public enum AppUpdateError: LocalizedError {
    case noRelease, rateLimited, invalidRelease, server(Int)
    public var errorDescription: String? {
        switch self {
        case .noRelease: return "No published Postino release was found on GitHub. Try again later."
        case .rateLimited: return "GitHub is limiting update checks right now. Please try again later."
        case .invalidRelease: return "GitHub returned release information that Postino could not read. Please try again later."
        case .server(let status): return "GitHub could not complete the update check (HTTP \(status)). Please try again later."
        }
    }
}

public final class AppUpdateChecker {
    public static let endpoint = URL(string: "https://api.github.com/repos/Dome015/postino/releases/latest")!
    private let session: URLSession
    public init(session: URLSession? = nil) {
        if let session { self.session = session } else {
            let configuration = URLSessionConfiguration.ephemeral
            configuration.httpShouldSetCookies = false
            configuration.requestCachePolicy = .reloadIgnoringLocalCacheData
            configuration.timeoutIntervalForRequest = 20
            configuration.timeoutIntervalForResource = 30
            self.session = URLSession(configuration: configuration)
        }
    }
    /// Completion runs on URLSession's delegate queue; callers own UI dispatch.
    public func check(installed: InstalledRelease, completion: @escaping (Result<AppUpdateResult, Error>) -> Void) {
        var request = URLRequest(url: Self.endpoint)
        request.setValue("application/vnd.github+json", forHTTPHeaderField: "Accept")
        request.setValue("2026-03-10", forHTTPHeaderField: "X-GitHub-Api-Version")
        request.setValue("Postino-Update-Checker", forHTTPHeaderField: "User-Agent")
        session.dataTask(with: request) { data, response, error in
            if let error { completion(.failure(error)); return }
            do {
                guard let response = response as? HTTPURLResponse else { throw AppUpdateError.invalidRelease }
                switch response.statusCode {
                case 200: break
                case 404: throw AppUpdateError.noRelease
                case 403, 429: throw AppUpdateError.rateLimited
                default: throw AppUpdateError.server(response.statusCode)
                }
                guard let data, data.count <= 1_000_000 else { throw AppUpdateError.invalidRelease }
                let release: AppRelease
                do { release = try JSONDecoder().decode(AppRelease.self, from: data) }
                catch { throw AppUpdateError.invalidRelease }
                completion(.success(try Self.evaluate(release, installed: installed)))
            } catch { completion(.failure(error)) }
        }.resume()
    }
    public static func evaluate(_ release: AppRelease, installed: InstalledRelease) throws -> AppUpdateResult {
        guard !release.draft, !release.prerelease, !release.tag.isEmpty,
              release.url.scheme == "https", release.url.host == "github.com",
              release.url.user == nil, release.url.password == nil, release.url.port == nil,
              release.url.path.hasPrefix("/Dome015/postino/releases/tag/"),
              let published = release.publishedAt.flatMap(InstalledRelease.date) else { throw AppUpdateError.invalidRelease }
        // A release is published after its own bundle is built.
        if installed.tag == release.tag { return .current }
        guard let builtAt = installed.builtAt else { return .unknownBuild(release) }
        return published > builtAt ? .available(release) : .current
    }
}
